import React from "react";
import { useAuth } from "../../Context/AuthContext";
import { useEffect, useState } from "react";
import {
  collection,
  doc,
  query,
  onSnapshot,
  orderBy,
  addDoc,
} from "firebase/firestore";
import db from "../../firebase";
import { bad_words_arr } from "./Forbidden_words";

const CommentsSection = (props) => {
  const user = useAuth();
  const [comment, setComment] = useState("");
  const [comments, setComments] = useState([]);
  const pollId = props.pollid; // Get the poll ID from props
  const commentsRef = collection(doc(db, "polls", pollId), "comments"); // Reference to the comments subcollection
  const [previewUrl, setPreviewUrl] = useState(null);

  useEffect(() => {
    const q = query(commentsRef, orderBy("timestamp", "desc"));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setComments(snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() })));
    });

    return unsubscribe;
  }, [pollId]); // Re-run the effect when pollId changes

  const addComment = async (comment) => {
    try {
      for (let word of bad_words_arr) {
        if (comment.toLowerCase().includes(word)) {
          alert(
            "Your comment contains forbidden words " +
              `"${word.replace(/.(?=.{2,}$)/g, "*")}"`
          );
          return;
        }
      }

      const isGif =
        comment.startsWith("http") &&
        (comment.endsWith(".gif") || comment.endsWith(".gifv"));

      await addDoc(commentsRef, {
        text: isGif ? "" : comment,
        gif: isGif ? comment : "",
        timestamp: new Date(),
        user: {
          uid: user.uid,
          displayName: user.displayName,
          photoURL: user.photoURL,
        },
      });
    } catch (e) {
      console.error("Error adding document: ", e);
    }
  };
  const handleKeyDown = (event) => {
    if (event.key === "Enter") {
      event.preventDefault();

      if (comment.trim() === "") return;

      if (!user) {
        alert("You need to log in to comment.");
        return;
      }

      addComment(comment);
      setComment(""); // Clear the input field
    }
  };

  const handleChange = (event) => {
    setComment(event.target.value);

    const isImage =
      event.target.value.startsWith("http") &&
      (event.target.value.endsWith(".png") ||
        event.target.value.endsWith(".jpg") ||
        event.target.value.endsWith(".jpeg") ||
        event.target.value.endsWith(".gif") ||
        event.target.value.endsWith(".gifv"));

    if (!isImage) {
      setPreviewUrl(null);
    }
  };

  const handlePaste = (event) => {
    const paste = (event.clipboardData || window.clipboardData).getData("text");
    const isImage =
      paste.startsWith("http") &&
      (paste.endsWith(".png") ||
        paste.endsWith(".jpg") ||
        paste.endsWith(".jpeg") ||
        paste.endsWith(".gif") ||
        paste.endsWith(".gifv"));

    if (isImage) {
      setPreviewUrl(paste);
    }
  };

  return (
    <div className="comments">
      <h1 className="title">Comments</h1>
      <div className="comment_container">
        <input
          value={comment}
          onChange={handleChange}
          onPaste={handlePaste}
          onKeyDown={handleKeyDown}
          type="text"
          placeholder="comment.."
          style={{
            backgroundImage: previewUrl ? `url(${previewUrl})` : "none",
            backgroundSize: "contain",
            padding: "10px",
            backgroundPosition: "right",
            backgroundRepeat: "no-repeat",
          }}
        />

        <div className="comment_list">
          {comments.map((comment) => (
            <div className="comment" key={comment.id}>
              <div className="profile">
                <div className="image">
                  <img src={comment.user.photoURL} />
                </div>
              </div>
              <div className="comment_text">
                <h5 className="username">{comment.user.displayName}</h5>
                {comment.text && <p className="main_comment">{comment.text}</p>}
                {comment.gif && (
                  <img className="main_comment_img" src={comment.gif} />
                )}{" "}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default CommentsSection;
