import React, { useEffect, useState } from "react";
import {
  doc,
  getDoc,
  runTransaction,
  onSnapshot,
  increment,
} from "firebase/firestore";
import db from "../../firebase";
import { useParams } from "react-router-dom";
import CommentsSection from "./CommentsSection";
import { useAuth } from "../../Context/AuthContext";
import AnalyticsSection from "./AnalyticsSection";

const PollSection = () => {
  const user = useAuth();
  const [poll, setPoll] = useState(null);
  const [liveCount, setLiveCount] = useState(0);
  const [hasVoted, setHasVoted] = useState(false);

  const { pollid } = useParams();
  useEffect(() => {
    const fetchPoll = async () => {
      const docRef = doc(db, "polls", pollid);
      const docSnap = await getDoc(docRef);

      if (docSnap.exists()) {
        setPoll({ ...docSnap.data(), id: docSnap.id });
        setLiveCount(docSnap.data().live_count);
      } else {
        console.log("No such document!");
      }
    };

    fetchPoll();
  }, [pollid]);

  useEffect(() => {
    const docRef = doc(db, "polls", pollid);

    const unsubscribe = onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        setPoll({ ...docSnap.data(), id: docSnap.id });
        setLiveCount(docSnap.data().live_count);

        const uid = user ? user.uid : null;
        if (uid && docSnap.data().voters && docSnap.data().voters[uid]) {
          setHasVoted(true);
        } else if (
          !uid &&
          localStorage.getItem("guestId") &&
          docSnap.data().voters &&
          docSnap.data().voters[localStorage.getItem("guestId")]
        ) {
          setHasVoted(true);
        }
      } else {
        console.log("No such document!");
      }
    });

    return () => {
      unsubscribe();
    };
  }, [pollid]);

  return (
    <div className="poll_section_main">
      <div className="poll_main">
        <span className="status">
          {liveCount} {liveCount === 1 ? "person " : "people "}
          live on this vote channel
        </span>
        <div className="poll">
          {poll &&
            Object.values(poll.options).map((option, i) => {
              const uid = user ? user.uid : null;
              const userVote = poll.voters ? poll.voters[uid] : null;

              return (
                <div
                  className="poll_option"
                  onClick={
                    hasVoted
                      ? null
                      : async () => {
                          setHasVoted(true);
                          const docRef = doc(db, "polls", pollid);

                          let uid = user ? user.uid : null;
                          const isStrict = poll ? poll.isStrict : false;

                          if (!uid) {
                            if (isStrict) {
                              alert(
                                "You must be logged in to vote for this poll!"
                              );
                              return;
                            }

                            uid = localStorage.getItem("guestId");
                            if (!uid) {
                              uid = Math.random().toString(36).substring(2);
                              localStorage.setItem("guestId", uid);
                            }
                          }

                          setPoll((prevPoll) => {
                            const newOptions = prevPoll.options.map((o) =>
                              o.text === option.text
                                ? { ...o, votes: o.votes + 1 }
                                : o
                            );
                            return {
                              ...prevPoll,
                              options: newOptions,
                              total_votes: prevPoll.total_votes + 1,
                              voters: {
                                ...prevPoll.voters,
                                [uid]: option.text,
                              },
                            };
                          });

                          await runTransaction(db, async (transaction) => {
                            const docSnap = await transaction.get(docRef);

                            if (!docSnap.exists()) {
                              throw "Document does not exist!";
                            }

                            const data = docSnap.data();
                            if (data.voters && data.voters[uid]) {
                              return;
                            }
                            const newOptions = data.options.map((o) =>
                              o.text === option.text
                                ? { ...o, votes: o.votes + 1 }
                                : o
                            );

                            transaction.update(docRef, {
                              options: newOptions,
                              total_votes: increment(1),
                              voters: { ...data.voters, [uid]: option.text },
                            });
                          });

                          const docSnap = await getDoc(docRef);
                          if (docSnap.exists()) {
                            setPoll({ ...docSnap.data(), id: docSnap.id });
                          }
                        }
                  }
                  key={i}
                  style={hasVoted ? { pointerEvents: "none" } : {}}
                >
                  <span className="option">{option.text}</span>
                  <div
                    style={{
                      width: `${(option.votes / poll.total_votes) * 100}%`,
                    }}
                    className={`bar ${
                      poll.voters[uid] === option.text
                        ? "active"
                        : "" ||
                          poll.voters[localStorage.getItem("guestId")] ===
                            option.text
                        ? "active"
                        : ""
                    } `}
                  ></div>
                  <span className="vote_count">{option.votes}</span>
                </div>
              );
            })}
        </div>
      </div>
      <CommentsSection pollid={pollid} />
      <AnalyticsSection pollid={pollid} />
    </div>
  );
};

export default PollSection;
